import { shallowRef } from 'vue'

const DEFAULT_DURATION = 4500
const MAX_TOASTS = 5

/** @typedef {'success'|'danger'|'warning'|'info'|'primary'} ToastVariant */

let idSeq = 0

/** Estado singleton compartilhado por todos os chamadores do composable */
const toasts = shallowRef([])

/** @type {Map<number, ReturnType<typeof setTimeout>>} */
const timers = new Map()

function clearTimer(id) {
  const t = timers.get(id)
  if (t) {
    clearTimeout(t)
    timers.delete(id)
  }
}

/**
 * @param {object} opts
 * @param {ToastVariant} opts.variant
 * @param {string} opts.message
 * @param {string} [opts.title]
 * @param {number} [opts.duration] ms; 0 = sem auto-dismiss
 */
function push({ variant, message, title = '', duration = DEFAULT_DURATION }) {
  const id = ++idSeq
  const item = { id, variant, message, title }

  const next = [...toasts.value, item]
  if (next.length > MAX_TOASTS) {
    next.slice(0, next.length - MAX_TOASTS).forEach((t) => clearTimer(t.id))
  }
  toasts.value = next.slice(-MAX_TOASTS)

  if (duration > 0) {
    const timer = setTimeout(() => remove(id), duration)
    timers.set(id, timer)
  }

  return id
}

function remove(id) {
  clearTimer(id)
  toasts.value = toasts.value.filter((t) => t.id !== id)
}

function clear() {
  toasts.value.forEach((t) => clearTimer(t.id))
  toasts.value = []
}

function pickPushArgs(message, opts, variant, defaultDuration = DEFAULT_DURATION) {
  return {
    variant,
    message,
    title: opts.title,
    duration: opts.duration !== undefined ? opts.duration : defaultDuration,
  }
}

export function useNotifications() {
  return {
    toasts,
    push,
    remove,
    clear,
    success: (message, opts = {}) => push(pickPushArgs(message, opts, 'success')),
    error: (message, opts = {}) =>
      push(pickPushArgs(message, opts, 'danger', 6000)),
    warning: (message, opts = {}) => push(pickPushArgs(message, opts, 'warning')),
    info: (message, opts = {}) => push(pickPushArgs(message, opts, 'info')),
  }
}
