<template>
  <Teleport to="body">
    <div
      class="app-notifications"
      role="region"
      aria-label="Notificações"
      :aria-live="assertiveLive ? 'assertive' : 'polite'"
      aria-relevant="additions text"
    >
      <TransitionGroup name="app-toast" tag="div" class="app-notifications__stack">
        <div
          v-for="toast in toasts"
          :key="toast.id"
          :class="['alert', 'shadow-sm', 'app-notifications__item', alertClass(toast.variant)]"
          role="alert"
        >
          <div class="app-notifications__body">
            <strong v-if="toast.title" class="d-block">{{ toast.title }}</strong>
            <span class="app-notifications__msg">{{ toast.message }}</span>
          </div>
          <button
            type="button"
            class="btn-close app-notifications__close"
            aria-label="Fechar notificação"
            @click="remove(toast.id)"
          />
        </div>
      </TransitionGroup>
    </div>
  </Teleport>
</template>

<script>
import { computed } from 'vue'
import { useNotifications } from '@/composables/useNotifications.js'

const VARIANT_CLASS = {
  success: 'alert-success',
  danger: 'alert-danger',
  warning: 'alert-warning',
  info: 'alert-info',
  primary: 'alert-primary',
}

export default {
  name: 'NotificationContainer',
  setup() {
    const { toasts, remove } = useNotifications()

    const assertiveLive = computed(() =>
      toasts.value.some((t) => t.variant === 'danger' || t.variant === 'warning')
    )

    function alertClass(variant) {
      return VARIANT_CLASS[variant] || 'alert-secondary'
    }

    return { toasts, remove, assertiveLive, alertClass }
  },
}
</script>

<style scoped>
.app-notifications {
  position: fixed;
  top: 1rem;
  right: 1rem;
  left: auto;
  z-index: 1080;
  max-width: min(420px, calc(100vw - 2rem));
  pointer-events: none;
}

.app-notifications__stack {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  align-items: flex-end;
}

.app-notifications__item {
  pointer-events: auto;
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  margin: 0;
  width: 100%;
  text-align: left;
}

.app-notifications__body {
  flex: 1;
  min-width: 0;
}

.app-notifications__msg {
  word-break: break-word;
}

.app-notifications__close {
  flex-shrink: 0;
  margin-top: 0.15rem;
}

/* Transições */
.app-toast-enter-active,
.app-toast-leave-active {
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.app-toast-enter-from {
  opacity: 0;
  transform: translateX(0.75rem);
}

.app-toast-leave-to {
  opacity: 0;
  transform: translateY(-0.35rem);
}

.app-toast-move {
  transition: transform 0.2s ease;
}
</style>
